sql.q_45b6147013797539:
WITH snapshot_users AS (
  SELECT canonical_user_id FROM fact_user_cohorts FINAL
  WHERE auth_user_id = {auth_user_id:String}
    AND warehouse_version = {warehouse_version:String}
    AND classification_version = {classification_version:String}
)
SELECT sumIf(gross_amount_usd, is_success = 1) gross,
  sumIf(gross_amount_usd, is_success = 1) - sum(floor(refund_amount_usd * 100 + 0.5) / 100) net
FROM analytics_transactions FINAL
WHERE auth_user_id = {auth_user_id:String}
  AND toDate(event_time) = toDate({break_day:String})
  AND user_id NOT IN (SELECT canonical_user_id FROM snapshot_users)
FORMAT JSONEachRow

sql.q_5ac44c4d99f0a523:
WITH snapshot_users AS (
  SELECT canonical_user_id FROM fact_user_cohorts FINAL
  WHERE auth_user_id = {auth_user_id:String}
    AND warehouse_version = {warehouse_version:String}
    AND classification_version = {classification_version:String}
)
SELECT toString(toDate(event_time)) day,
  sumIf(gross_amount_usd, is_success = 1) gross,
  sum(floor(refund_amount_usd * 100 + 0.5) / 100) refunds,
  countIf(is_success = 1) rows_scanned
FROM analytics_transactions FINAL
WHERE auth_user_id = {auth_user_id:String}
  AND user_id NOT IN (SELECT canonical_user_id FROM snapshot_users)
GROUP BY day ORDER BY day
FORMAT JSONEachRow

sql.q_a10c41989a029ca4:
SELECT toString(max(fc.trial_event_time)) data_through, count() n
FROM fact_user_cohorts AS fc FINAL
WHERE fc.auth_user_id = {auth_user_id:String}
  AND fc.warehouse_version = {warehouse_version:String}
  AND fc.classification_version = {classification_version:String}
FORMAT JSONEachRow

sql.q_ab4e09e5512e4296:
SELECT lowerUTF8(trim(BOTH ' ' FROM normalized_email)) email,
        toString(cohort_date) cohort_date, funnel, campaign_path
      FROM fact_user_cohorts FINAL
      WHERE auth_user_id = {auth_user_id:String}
        AND warehouse_version = {warehouse_version:String}
        AND classification_version = {classification_version:String}
        AND normalized_email != ''
      FORMAT JSONEachRow

sql.q_d9879d386e042ed0:
SELECT count() AS transactions_scanned, uniqExact(user_id) AS users_scanned,
      countIf(fx_status IN ('missing_currency','missing_fx_rate','invalid_amount')) AS missing_fx
      FROM analytics_transactions FINAL WHERE auth_user_id = {auth_user_id:String}

sql.q_fab178e86d557ae4:
SELECT count() snapshot_rows,
    uniqExact(canonical_user_id) snapshot_unique_users,
    count() - uniqExact(canonical_user_id) snapshot_duplicate_users
  FROM fact_user_cohorts FINAL
  WHERE auth_user_id = {auth_user_id:String}
    AND warehouse_version = {warehouse_version:String}
    AND classification_version = {classification_version:String}
  FORMAT JSONEachRow
